def fizzbuzz(n: int) -> list[str]:
    result: list[str] = []
    for i in range(1, n + 1):
        value = ""
        if i % 3 == 0:
            value += "Fizz"
        if i % 5 == 0:
            value += "Buzz"
        if i % 7 == 0:
            value += "Bazz"
        result.append(value if value else str(i))
    return result
