import re

_INT_RE = re.compile(r"[+-]?[0-9]+")

def parse_kv(s: str) -> dict:
    result = {}
    for part in s.split(";"):
        part = part.strip()
        if not part:
            continue
        if "=" not in part:
            raise ValueError(f"Invalid key-value pair: {part!r}")
        key, value = part.split("=", 1)
        if _INT_RE.fullmatch(value):
            value = int(value)
        result[key] = value
    return result
```

