def rle_encode(s: str) -> str:
    if not s:
        return ""

    encoded = []
    current = s[0]
    count = 1

    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            encoded.append(f"{count}{current}")
            current = ch
            count = 1

    encoded.append(f"{count}{current}")
    return "".join(encoded)


def rle_decode(s: str) -> str:
    if not s:
        raise ValueError("empty string")

    decoded = []
    i = 0
    n = len(s)

    while i < n:
        start = i
        while i < n and s[i].isdigit():
            i += 1

        if i == start:
            raise ValueError("missing count")

        count = int(s[start:i])

        if count == 0:
            raise ValueError("zero count")

        if i >= n:
            raise ValueError("trailing digits")

        decoded.append(s[i] * count)
        i += 1

    return "".join(decoded)
