def balanced(s: str) -> bool:
    stack = []
    in_single = False
    in_double = False

    matching = {
        ")": "(",
        "]": "[",
        "}": "{",
    }
    openers = {"(", "[", "{"}

    for ch in s:
        if in_single:
            if ch == "'":
                in_single = False
            continue

        if in_double:
            if ch == '"':
                in_double = False
            continue

        if ch == "'":
            in_single = True
        elif ch == '"':
            in_double = True
        elif ch in openers:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

    return not stack
```

