def edit_distance(a: str, b: str) -> int:
    if a == b:
        return 0

    if len(a) > len(b):
        a, b = b, a

    m = len(a)
    if m == 0:
        return len(b)

    dp = list(range(m + 1))

    for i, cb in enumerate(b, 1):
        prev_diag = dp[0]
        dp[0] = i

        for j, ca in enumerate(a, 1):
            old = dp[j]
            cost = 0 if ca == cb else 1

            best = old + 1
            insert = dp[j - 1] + 1
            if insert < best:
                best = insert

            substitute = prev_diag + cost
            if substitute < best:
                best = substitute

            dp[j] = best
            prev_diag = old

    return dp[m]
```

